<script setup>
import {ref,computed,watch} from 'vue'
import EvaluationArchive from './EvaluationArchive.vue'
import {api,number,resultName} from './api.mjs'
const props=defineProps({tasks:Array,published:Array,standardId:String,selectedId:String,busy:Boolean,evaluationEnabled:Boolean,releaseId:String,evaluationTasks:Array})
const emit=defineEmits(['select','metadata','cleanup','stop','submit'])
const records=ref(false),search=ref(''),page=ref(1),group=ref('all'),compareIds=ref([]),comparisons=ref([]),compareError=ref(''),comparing=ref(false)
const role=t=>t.id===props.standardId?'current-default':t.builtin?'historical-release':t.request?.researchSchemeId||t.request?.modelFamily==='grid-continuous-v1'?'research-candidate':'user-result'
const roleName=t=>({'current-default':'当前默认','historical-release':'历史发布','research-candidate':'研究候选','user-result':'用户成果'})[role(t)]
const catalog=computed(()=>[...(props.published||[]).map(t=>({...t,builtin:true,status:'succeeded'})),...(props.tasks||[])])
const filtered=computed(()=>catalog.value.filter(t=>!t.trashed&&(group.value==='all'||role(t)===group.value)&&(!search.value||(t.name||t.displayName||'').includes(search.value)||t.id.includes(search.value))))
const visible=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10))
watch([search,group],()=>page.value=1)
let ticket=0
watch(compareIds,async ids=>{const current=++ticket;comparisons.value=[];compareError.value='';if(ids.length<2)return;comparing.value=true;try{const data=await Promise.all(ids.map(id=>api('result-summary?resultId='+encodeURIComponent(id))));if(current===ticket)comparisons.value=data}catch(e){if(current===ticket)compareError.value=e.message}finally{if(current===ticket)comparing.value=false}},{deep:true})
const compareYears=computed(()=>[...new Set(comparisons.value.flatMap(s=>Object.keys(s.evaluation.annual)))].sort())
const compareDifferences=computed(()=>{if(comparisons.value.length<2)return[];const rows=comparisons.value;return [['初始化口径',s=>s.evaluation.mode],['输入版本',s=>s.inputId],['观测质量规则',s=>s.evaluation.qualityProfile],['计水范围',s=>s.inflowComplete===false?'verified-only':'legacy-assumption']].filter(([,read])=>new Set(rows.map(read)).size>1).map(([name])=>name)})
</script>
<template>
 <div class="result-entry"><button :class="{primary:selectedId===standardId}" @click="records=false;emit('select',standardId)">当前默认成果</button><button :class="{primary:records}" @click="records=!records">成果记录与比较 <span>{{catalog.length}}</span></button></div>
 <section v-if="records" class="panel"><div class="panel-title"><h3>成果记录</h3><input type="search" v-model="search" placeholder="查找名称或成果编号"></div><div class="result-group-controls"><button v-for="g in [['all','全部'],['current-default','当前默认'],['research-candidate','研究候选'],['historical-release','历史发布'],['user-result','用户成果']]" :key="g[0]" :class="{primary:group===g[0]}" @click="group=g[0]">{{g[1]}}</button><span class="muted">勾选两至三套成果查看口径与年度指标</span></div><div class="table-wrap"><table><thead><tr><th>比较</th><th>成果与身份</th><th>计算时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in visible" :key="t.id" :class="{selected:t.id===selectedId}"><td><input type="checkbox" v-model="compareIds" :value="t.id" :disabled="t.status!=='succeeded'||(!compareIds.includes(t.id)&&compareIds.length>=3)" :aria-label="'比较 '+resultName(t)"></td><td><button class="link" @click="emit('select',t.id)">{{t.displayName||resultName(t)}}</button><div><span class="badge">{{roleName(t)}}</span></div></td><td>{{(t.created_at||t.publishedAt||'').slice(0,16).replace('T',' ')||'内置冻结成果'}}</td><td>{{({succeeded:'已完成',running:'计算中',queued:'排队中',failed:'失败',cancelled:'已停止',interrupted:'已中断',stopping:'正在停止'})[t.status]}}</td><td><button v-if="['running','queued','stopping'].includes(t.status)" @click="emit('stop',t.id)">停止</button><button v-else-if="!t.builtin" @click="emit('metadata',t,{favorite:!t.favorite})">{{t.favorite?'取消收藏':'收藏'}}</button></td></tr></tbody></table></div><p v-if="!filtered.length" class="muted">当前条件下没有成果。</p><div v-if="filtered.length>10" class="pagination"><button :disabled="page===1" @click="page--">上一页</button><span>{{page}} / {{Math.ceil(filtered.length/10)}}</span><button :disabled="page*10>=filtered.length" @click="page++">下一页</button></div>
 <div v-if="compareIds.length>=2" class="result-compare"><h3>评价口径核对</h3><p v-if="comparing">正在读取冻结评价摘要…</p><p v-if="compareError" class="warning">{{compareError}}</p><template v-if="comparisons.length"><p class="warning">{{compareDifferences.length?'以下条件不同：'+compareDifferences.join('、')+'。年度存量指标仅作诊断，不能直接排名。':'身份口径一致；仍须冻结共同有效日期后才能形成正式优选结论。'}}</p><div class="table-wrap"><table><thead><tr><th>成果</th><th>初始化</th><th>输入</th><th>覆盖</th></tr></thead><tbody><tr v-for="s in comparisons" :key="s.id"><td>{{s.name}}</td><td>{{s.evaluation.label}}</td><td>{{s.inputId}}</td><td>{{s.displayCoverage.start?.slice(0,10)}}—{{s.displayCoverage.end?.slice(0,10)}}</td></tr></tbody></table></div><div class="table-wrap"><table><thead><tr><th>成果 / 年份</th><th>湖位 RMSE / m</th><th>湖位日数</th><th>杜加 NSE</th><th>径流偏差 / %</th><th>流量日数</th></tr></thead><tbody><template v-for="s in comparisons" :key="s.id"><tr v-for="y in compareYears" :key="s.id+y"><td>{{s.name}} · {{y}}</td><td>{{number(s.evaluation.annual[y]?.lake?.rmse,4)}}</td><td>{{s.evaluation.annual[y]?.lake?.count||'无合格资料'}}</td><td>{{number(s.evaluation.annual[y]?.flow?.nse,4)}}</td><td>{{number(s.evaluation.annual[y]?.flow?.pbias,2)}}</td><td>{{s.evaluation.annual[y]?.flow?.count||'无合格资料'}}</td></tr></template></tbody></table></div></template></div></section>
 <EvaluationArchive v-if="evaluationEnabled" :records="catalog" :tasks="evaluationTasks||tasks" :release-id="releaseId" :default-id="standardId" :busy="busy" @submit="emit('submit',$event)"/>
 <slot/>
</template>
